-- =====================================================================
-- Ortografía de las historias de los embajadores en una base ya poblada.
-- Correcciones en scripts/lib/story-fixes.mjs (también se aplican al generar la semilla).
-- Solo actualiza un embajador si su historia sigue igual a la que se revisó: si el
-- embajador la editó desde su panel, no se toca.
-- Ejecútalo en Supabase > SQL Editor. Corre en una transacción.
-- =====================================================================
begin;
set local app.trusted = 'on';

-- EM0001 · La Petit Huila
update public.ambassadors set
  story_origin = 'En La Petit Huila decidimos iniciar debido a la necesidad manifiesta de conocidos y de nosotros mismos de poder disfrutar un buen cafecito en diferentes partes del país (especialmente cuando viajamos), acompañados de un snack perfecto, ligero y transportable; siempre nos costaba y cuesta encontrar unas deliciosas achiras tradicionales (no industriales) con alguna variedad de café especial por fuera del Huila.',
  story_present = 'Actualmente, y tras poner a prueba nuestra extensa experiencia cafetera y achirera (abuelos, padres y ahora nosotros), tenemos para el encanto de nuestros clientes y visitantes el casamiento más representativo y gustoso de nuestro departamento: achiras con cafecito especial 100 % opita. Contamos con instalaciones adecuadas y certificadas para la producción de las achiras y en nuestras fincas (familiares de nuestros abuelos, padres y tíos) procesamos los cafés especiales.',
  story_future = 'La mejora continua es el pilar básico de La Petit Huila. Nuestro objetivo siempre seguirá siendo conquistar a las personas amantes del café y de snacks saludables. Numerosos coffee shops, brunchs, hoteles, restaurantes y coffee lovers conquistados con nuestros sabores seguirán creciendo y manteniéndonos en una bonita y extensa relación recíproca de alegría y compromiso con la comunidad cafetera y de productos de origen.'
where code = 'EM0001'
  and story_origin is not distinct from 'En la Petit Huila, decidimos iniciar debido a la necesidad manifiesta de conocidos y de nosotros mismos de poder disfrutar un buen cafecito en diferentes partes del país (especialmente cuando viajamos) acompañados de un snack perfecto, ligero y transportable; siempre nos costaba y cuesta encontrar unas deliciosas achiras tradicionales (no industriales) con alguna variedad de café especial por fuera del Huila.'
  and story_present is not distinct from 'Actualmente y tras poner a prueba nuestra extensa experiencia cafetera y achirera (abuelos, padres y ahora nosotros) tenemos para el encanto de nuestros clientes y visitantes el casamiento mas representativo y gustoso de nuestro departamento: achiras con cafecito especial 100 % opita. Contamos con instalaciones adecuadas y certificadas para la producción de las achiras y en nuestras fincas (familiar de nuestros abuelos, padres y tíos) procesamos los cafés especiales.'
  and story_future is not distinct from 'La mejora continua es el pilar básico de La Petit Huila. Nuestro objetivo siempre seguirá siendo conquistar a las personas amantes del café y de snacks saludables. Numerosos coffee shops, brunchs, hoteles, restaurantes y coffee lovers conquistados con nuestros sabores seguiran creciendo y manteniéndonos en una bonita y extensa relación reciproca de alegría y compromiso con la comunidad cafetera y de productos de origen.';

-- EM0002 · ADAMES Resortwear
update public.ambassadors set
  story_origin = 'ADAMES nació en Neiva antes de un viaje a la costa, por una frustración personal: el mercado solo ofrecía lo mismo de siempre y no había trajes de baño hermosos, diferentes y discretos que respetaran el deseo de cubrir ciertas partes del cuerpo. Al ver que yo estaba "bregando", entendí que las mujeres de tallas grandes y mayores de 50 años vivían la misma exclusión. Decidí crear la solución.',
  story_present = 'Nuestro viaje ha sido una evolución constante: nacimos con el deseo de transformar la moda playera tradicional y hoy logramos crear colecciones completas que fusionan la moldería anatómica con el minimalismo orgánico. En el camino hemos aprendido que la verdadera belleza requiere estructura; por eso, cada uno de nuestros trajes de baño está diseñado para brindar soporte, seguridad y elegancia a los cuerpos reales. Hoy no te ofrecemos solo una prenda, te entregamos un negocio honesto, piezas de alta calidad y el respaldo de una marca real que celebra tu silueta en cada detalle.',
  story_future = 'Mañana nos proyectamos consolidando a ADAMES como un referente de lujo relajado y sofisticación, con la meta clara de abrir las puertas de nuestro primer "Santuario" físico en Neiva para el 2027. Nuestros sueños más cercanos están enfocados en expandir este Universo de Vestuario, llevando la fusión del Swimwear técnico, el Resortwear de linos y el arte del upcycling artesanal a vitrinas nacionales. Queremos seguir escalando el negocio de forma estructurada para demostrar que el diseño consciente, la innovación y la empatía pueden transformar la moda, logrando que cada vez más mujeres recuperen la soberanía y la confianza sobre su propio cuerpo.'
where code = 'EM0002'
  and story_origin is not distinct from 'ADAMES nació en Neiva antes de un viaje a la costa, por una frustración personal: el mercado solo ofrecía lo mismo de siempre y no había trajes de baño hermosos, diferentes y discretos que respetaran el deseo de cubrir ciertas partes del cuerpo. Al ver que yo estaba "bregando", entendí que las mujeres de tallas grandes y mayores de 50 años vivían la misma exclusión. Decidí crear la solución.'
  and story_present is not distinct from 'Nuestro viaje ha sido una evolución constante, nacimos con el deseo de transformar la moda playera tradicional y hoy logramos crear colecciones completas que fusionan la moldería anatómica con el minimalismo orgánico. En el camino hemos aprendido que la verdadera belleza requiere estructura; por eso, cada una de nuestros trajes de baño está diseñada para brindar soporte, seguridad y elegancia a los cuerpos reales.  Hoy no te ofrecemos solo una prenda, te entregamos un negocio honesto, piezas de alta calidad y el respaldo de una marca real que celebra tu silueta en cada detalle.'
  and story_future is not distinct from 'Mañana nos proyectamos consolidando a ADAMES como un referente de lujo relajado y sofisticación, con la meta clara de abrir las puertas de nuestro primer "Santuario" físico en Neiva para el 2027. Nuestros sueños más cercanos están enfocados en expandir este Universo de Vestuario, llevando la fusión del Swimwear técnico, el Resortwear de linos y el arte del upcycling artesanal a vitrinas nacionales. Queremos seguir escalando el negocio de forma estructurada para demostrar que el diseño consciente, la innovación y la empatía pueden transformar la moda, logrando que cada vez más mujeres recuperen la soberanía y la confianza sobre su propio cuerpo.';

-- EM0004 · Chocolate Mamá Susana
update public.ambassadors set
  story_origin = 'Chocolate Mamá Susana nació del amor por las tradiciones de nuestra tierra y del deseo de que la costumbre de compartir una taza de chocolate nunca desapareciera. La inspiración lleva el nombre de mi mamá, Susana, quien durante toda su vida nos enseñó que alrededor del chocolate siempre había un espacio para la conversación, la unión familiar y el cariño.

Como microbiólogo y apasionado por la innovación, entendí que la mejor forma de preservar esa tradición era transformándola en una empresa que uniera conocimiento, calidad y cultura. Así comenzó este sueño: investigando, aprendiendo sobre el cacao, desarrollando recetas, participando en procesos de formación, concursos y proyectos de innovación, hasta lograr crear productos que respetan la esencia del chocolate artesanal, pero con una propuesta diferente.

Los primeros pasos no fueron fáciles. Fueron años de trabajo, de tocar puertas, de buscar oportunidades, de creer en una idea incluso cuando parecía lejana. Cada ensayo, cada error y cada aprendizaje fortalecieron la convicción de que el chocolate podía contar la historia de nuestro territorio y convertirse en un orgullo para Altamira y para el Huila.',
  story_present = 'Hoy Chocolate Mamá Susana es mucho más que una fábrica de chocolate: es un proyecto que preserva la tradición, impulsa el turismo, promueve la cultura del cacao y genera valor para nuestro territorio.

Contamos con una planta de producción especializada, con registro INVIMA, donde elaboramos chocolates artesanales con altos estándares de calidad. También abrimos las puertas de nuestra Casa del Chocolate, un espacio donde visitantes y habitantes pueden vivir experiencias alrededor del cacao, conocer su historia y descubrir los sabores que hacen único al Huila.

En el camino hemos vivido grandes satisfacciones, como obtener el reconocimiento a la Mejor Taza de Chocolate en FICCA 2024, consolidar alianzas con instituciones y emprendedores, y ver cómo cada vez más personas se enamoran de nuestra marca. Pero también hemos enfrentado desafíos, momentos de incertidumbre y obstáculos propios de emprender. Cada uno de ellos nos enseñó que el crecimiento se construye con disciplina, paciencia y perseverancia.

Hoy seguimos convencidos de nuestra propuesta de valor: hacer que la tradición sea lo innovador, demostrando que el patrimonio gastronómico puede convertirse en una experiencia moderna, auténtica y memorable.',
  story_future = 'Nuestro mayor sueño es que Chocolate Mamá Susana se convierta en un referente nacional e internacional del chocolate artesanal colombiano y que Altamira y el Huila sean reconocidos como un destino donde el cacao, la cultura y el turismo se encuentren.

Queremos seguir desarrollando productos innovadores con identidad regional, fortalecer nuestra Casa del Chocolate como un espacio de aprendizaje y experiencias, abrir nuevos mercados dentro y fuera del país y continuar trabajando de la mano con productores de cacao, artesanos y emprendedores que hacen parte de esta cadena de valor.

Más allá de crecer como empresa, queremos dejar un legado: demostrar que las tradiciones pueden convertirse en oportunidades de desarrollo, que los sueños construidos con esfuerzo sí son posibles y que una taza de chocolate puede contar la historia de una familia, de un pueblo y de toda una región.'
where code = 'EM0004'
  and story_origin is not distinct from 'Chocolate Mamá Susana nació del amor por las tradiciones de nuestra tierra y del deseo de que la costumbre de compartir una taza de chocolate nunca desapareciera. La inspiración lleva el nombre de mi mamá, Susana, quien durante toda su vida nos enseñó que alrededor del chocolate siempre había un espacio para la conversación, la unión familiar y el cariño.

Como microbiólogo y apasionado por la innovación, entendí que la mejor forma de preservar esa tradición era transformándola en una empresa que uniera conocimiento, calidad y cultura. Así comenzó este sueño: investigando, aprendiendo sobre el cacao, desarrollando recetas, participando en procesos de formación, concursos y proyectos de innovación, hasta lograr crear productos que respetan la esencia del chocolate artesanal, pero con una propuesta diferente.

Los primeros pasos no fueron fáciles. Fueron años de trabajo, de tocar puertas, de buscar oportunidades, de creer en una idea incluso cuando parecía lejana. Cada ensayo, cada error y cada aprendizaje fortalecieron la convicción de que el chocolate podía contar la historia de nuestro territorio y convertirse en un orgullo para Altamira y para el Huila.'
  and story_present is not distinct from 'Hoy Chocolate Mamá Susana es mucho más que una fábrica de chocolate: es un proyecto que preserva la tradición, impulsa el turismo, promueve la cultura del cacao y genera valor para nuestro territorio.

Contamos con una planta de producción especializada, con registro INVIMA, donde elaboramos chocolates artesanales con altos estándares de calidad. También abrimos las puertas de nuestra Casa del Chocolate, un espacio donde visitantes y habitantes pueden vivir experiencias alrededor del cacao, conocer su historia y descubrir los sabores que hacen único al Huila.

En el camino hemos vivido grandes satisfacciones, como obtener el reconocimiento a la Mejor Taza de Chocolate en FICCA 2024, consolidar alianzas con instituciones y emprendedores, y ver cómo cada vez más personas se enamoran de nuestra marca. Pero también hemos enfrentado desafíos, momentos de incertidumbre y obstáculos propios de emprender. Cada uno de ellos nos enseñó que el crecimiento se construye con disciplina, paciencia y perseverancia.

Hoy seguimos convencidos de nuestra propuesta de valor: hacer que la tradición sea lo innovador, demostrando que el patrimonio gastronómico puede convertirse en una experiencia moderna, auténtica y memorable.'
  and story_future is not distinct from 'Nuestro mayor sueño es que Chocolate Mamá Susana se convierta en un referente nacional e internacional del chocolate artesanal colombiano y que el Altamira y el Huila sea reconocido como un destino donde el cacao, la cultura y el turismo se encuentren.

Queremos seguir desarrollando productos innovadores con identidad regional, fortalecer nuestra Casa del Chocolate como un espacio de aprendizaje y experiencias, abrir nuevos mercados dentro y fuera del país y continuar trabajando de la mano con productores de cacao, artesanos y emprendedores que hacen parte de esta cadena de valor.

Más allá de crecer como empresa, queremos dejar un legado: demostrar que las tradiciones pueden convertirse en oportunidades de desarrollo, que los sueños construidos con esfuerzo sí son posibles y que una taza de chocolate puede contar la historia de una familia, de un pueblo y de toda una región.';

-- EM0005 · ARTBACU
update public.ambassadors set
  story_origin = 'Observamos la necesidad de un souvenir que resaltara la cultura y el turismo del Huila, y ante la situación de desempleo y la falta de oportunidades para mi hija en condición de discapacidad auditiva, nace el emprendimiento familiar ArtBaCu ARTE-BARR´-CULTURA. Iniciamos dándonos a conocer de feria en feria.',
  story_present = 'Actualmente estamos posicionados en el mercado regional, con gran recorrido en eventos locales y nacionales, cada día mejoramos con cada aporte que nos realizan nuestros clientes. En algunas ocasiones también hemos estado con los ánimos caídos debido a circunstancias del mercado, pero acá estamos listos para que cada colombiano y extranjero tenga un pedacito del Huila en su hogar, en su oficina y en su corazón.',
  story_future = 'Nuestro sueño es asistir a ferias internacionales, y la meta más cercana es ser la empresa de artesanías más reconocida del Huila y sus alrededores.'
where code = 'EM0005'
  and story_origin is not distinct from 'Observamos la necesidad de un souvenir que resaltara la cultura y el turismo del Huila, y ante la situación de desempleo y la falta de oportunidad para mi hija en condición de discapacidad auditiva nace el emprendimiento familiar ArtBaCu ARTE-BARR´-CULTURA, iniciamos dándonos a conocer de feria en feria'
  and story_present is not distinct from 'Actualmente estamos posesionados en el mercado regional, con gran recorrido en eventos locales y nacionales, cada día mejoramos con cada aporte que nos realizan nuestro clientes, en algunas ocasiones también hemos estado un los ánimos caídos debido a circunstancias del mercado , pero acá estamos listos para que cada colombiano y extranjero tenga un pedacito del Huila en su hogar oficina y en su corazón'
  and story_future is not distinct from 'Los sueños son asistir a ferias internacionales, la metas mas cercana es ser la empresa de artesanías mas reconocida del Huila y sus alrededores';

-- EM0006 · APIFIT
update public.ambassadors set
  story_origin = 'Apifit fue fundada en 2018 en Pitalito, Huila, por Leonardo Aguilera y Diana Méndez. Nació como un acto de amor y responsabilidad ambiental ante la alarmante pérdida global de abejas. Impulsados por el deseo de proteger la polinización local y la seguridad alimentaria, iniciamos un sueño con solo tres colmenas y un gran proceso de aprendizaje autónomo y rescate amigable de enjambres.
En el año 2020, en medio de la pandemia y con la llegada de nuevos socios estratégicos, nos estructuramos para responder a la creciente demanda de productos naturales y terapéuticos de la colmena. Hoy en día, somos un Negocio Verde en proceso de certificación que cuenta con cuatro líneas de acción que abarcan la nutrición saludable, insumos para apicultores, servicios de polinización dirigida a cultivos y educación ambiental.
Guiados por la convicción de que trabajar con las abejas requiere pasión antes que interés económico, ofrecemos productos y servicios con el valor de estar "hechos por abejas y cuidados con el amor de nuestros campesinos colombianos para tu bienestar". Nos proyectamos con firmeza para ser líderes nacionales, demostrando que una apicultura económicamente sustentable, socialmente incluyente y ambientalmente sostenible es el camino para un planeta feliz.',
  story_present = 'Hoy, ApiFit se encuentra en una emocionante fase de despegue y crecimiento continuo. Si miramos hacia atrás, el viaje ha sido una escuela constante de resistencia, amor y aprendizaje.
Empezamos en 2018 de forma totalmente autogestionada, aprendiendo sobre la marcha mediante cursos, videos y pruebas de campo con apenas tres colmenas. Al principio, el camino fue físicamente exigente: el rescate amigable de enjambres nos tomaba largas jornadas que se extendían hasta la madrugada. El gran reto inicial fue aprender a estructurar administrativamente una pasión para convertirla en una empresa organizada, algo que logramos consolidar con la llegada de socios estratégicos en 2020.
Lo que comenzó como un sueño de conservación hoy es una realidad diversa y sólida. Actualmente contamos con 4 líneas de acción activas: nutrición saludable (con un catálogo de 26 productos nutracéuticos derivados de la colmena), insumos y asesoría para nuevos apicultores (37 productos), servicios de polinización dirigida que aumentan hasta un 24% el rendimiento de los cultivos locales, y jornadas de educación ambiental con comunidades y universidades.
Hoy somos una compañía confiable, madura y con un alto estándar de calidad. Ya estamos certificados como Negocio Verde ante el Ministerio de Medio Ambiente y la CAM. Mantenemos intacta la filosofía de que a las abejas se les cuida con amor, y nos proyectamos con total firmeza para ser una empresa líder de la apicultura en Colombia.',
  story_future = 'En ApiFit miramos al futuro con la firme convicción de que el crecimiento económico debe ir de la mano con la preservación del planeta. Con la gran satisfacción de ser oficialmente un Negocio Verde certificado, nuestras metas y sueños más cercanos se centran en tres grandes hitos:
- Liderazgo Nacional: Nuestra meta principal a corto y mediano plazo es consolidarnos como una de las tres empresas líderes en Colombia en la producción y comercialización de productos auténticos y servicios apícolas, destacando siempre por nuestro alto nivel de calidad y confiabilidad.
- Potenciar nuestro impacto como Negocio Verde: Ahora que contamos con este sello ambiental, nuestro propósito es maximizar el impacto positivo en los ecosistemas y la sociedad. Queremos ser el referente nacional de cómo una empresa sostenible puede ofrecer bienestar real, garantizando productos 100% auténticos y naturales de la más alta calidad.
- Transformación del campo y seguridad alimentaria: Soñamos con expandir nuestras líneas de acción para seguir tecnificando a más familias campesinas (generándoles ingresos adicionales) y masificar los servicios de polinización dirigida. Queremos llevar los servicios ecosistémicos de las abejas a más regiones, demostrando a los agricultores que protegerlas incrementa notablemente el rendimiento y calidad de sus cosechas.
En definitiva, mañana nos vemos como el principal ejemplo en Colombia de que es posible tener una actividad altamente competitiva en el mercado, manteniendo intacto el amor por la naturaleza y nuestra esencia: entregar salud "hecha por abejas y cuidada con el amor de nuestros campesinos".'
where code = 'EM0006'
  and story_origin is not distinct from 'Apifit fue fundada en 2018 en Pitalito - Huila por Leonardo Aguilera y Diana Méndez, nació como un acto de amor y responsabilidad ambiental ante la alarmante pérdida global de abejas. Impulsados por el deseo de proteger la polinización local y la seguridad alimentaria, iniciamos un sueño con solo tres colmenas y un gran proceso de aprendizaje autónomo y rescate amigable de enjambres.
En el año 2020, en medio de la pandemia y con la llegada de nuevos socios estratégicos, nos estructuramos para responder a la creciente demanda de productos naturales y terapéuticos de la colmena. Hoy en día, somos un Negocio Verde en proceso de certificación que cuenta con cuatro líneas de acción que abarcan la nutrición saludable, insumos para apicultores, servicios de polinización dirigida a cultivos y educación ambiental.
Guiados por la convicción de que trabajar con las abejas requiere pasión antes que interés económico, ofrecemos productos y servicios con el valor de estar "hechos por abejas y cuidados con el amor de nuestros campesinos colombianos para tu bienestar". Nos proyectamos con firmeza para ser líderes nacionales, demostrando que una apicultura económicamente sustentable, socialmente incluyente y ambientalmente sostenible es el camino para un planeta feliz.'
  and story_present is not distinct from 'Hoy, ApiFit se encuentra en una emocionante fase de despegue y crecimiento continuo. Si miramos hacia atrás, el viaje ha sido una escuela constante de resistencia, amor y aprendizaje.
Empezamos en 2018 de forma totalmente autogestionada, aprendiendo sobre la marcha mediante cursos, videos y pruebas de campo con apenas tres colmenas. Al principio, el camino fue físicamente exigente: el rescate amigable de enjambres nos tomaba largas jornadas que se extendían hasta la madrugada. El gran reto inicial fue aprender a estructurar administrativamente una pasión para convertirla en una empresa organizada, algo que logramos consolidar con la llegada de socios estratégicos en 2020.
Lo que comenzó como un sueño de conservación hoy es una realidad diversa y sólida. Actualmente contamos con 4 líneas de acción activas: nutrición saludable (con un catálogo de 26 productos nutracéuticos derivados de la colmena), insumos y asesoría para nuevos apicultores (37 productos), servicios de polinización dirigida que aumentan hasta un 24% el rendimiento de los cultivos locales, y jornadas de educación ambiental con comunidades y universidades.
Hoy somos una compañía confiable, madura y con un alto estándar de calidad. Ya estamos certificados como Negocio Verde ante el Ministerio de Medio Ambiente y la CAM. Mantenemos intacta la filosofía de que a las abejas se les cuida con amor, y nos proyectamos con total firmeza para ser una empresas líder de la apicultura en Colombia.'
  and story_future is not distinct from 'En ApiFit miramos al futuro con la firme convicción de que el crecimiento económico debe ir de la mano con la preservación del planeta. Con la gran satisfacción de ser oficialmente un Negocio Verde certificado, nuestras metas y sueños más cercanos se centran en tres grandes hitos:
- Liderazgo Nacional: Nuestra meta principal a corto y mediano plazo es consolidarnos como una de las tres empresas líderes en Colombia en la producción y comercialización de productos auténticos y servicios apícolas, destacando siempre por nuestro alto nivel de calidad y confiabilidad.
- Potenciar nuestro impacto como Negocio Verde: Ahora que contamos con este sello ambiental, nuestro propósito es maximizar el impacto positivo en los ecosistemas y la sociedad. Queremos ser el referente nacional de cómo una empresa sostenible puede ofrecer bienestar real, garantizando productos 100% auténticos y naturales de la más alta calidad.
- Transformación del campo y seguridad alimentaria: Soñamos con expandir nuestras líneas de acción para seguir tecnificando a más familias campesinas (generándoles ingresos adicionales) y masificar los servicios de polinización dirigida. Queremos llevar los servicios ecosistémicos de las abejas a más regiones, demostrando a los agricultores que protegerlas incrementa notablemente el rendimiento y calidad de sus cosechas.
En definitiva, mañana nos vemos como el principal ejemplo en Colombia de que es posible tener una actividad altamente competitiva en el mercado, manteniendo intacto el amor por la naturaleza y nuestra esencia: entregar salud "hecha por abejas y cuidada con el amor de nuestros campesinos".';

-- EM0007 · Bambuqueras
update public.ambassadors set
  story_origin = 'La empresa Bambuqueras inició en el año 1988 bajo el nombre Bizcochería La Especial, con 2 personas al frente del negocio. Con el pasar de los años y el aumento de las ventas y el éxito de la empresa, nos vimos en la obligación de registrar nuestra marca. Al estar ya ocupado ese nombre con otra empresa, tuvimos que cambiar y renovar nuestro nombre. Actualmente somos Bambuqueras, un legado muy especial: somos los mismos de hace 38 años, con la misma receta y la misma tradición.',
  story_present = 'Hoy Bambuqueras, antes conocida como Bizcochería La Especial, es una empresa más organizada, comprometida y enfocada en la calidad. A lo largo de este camino hemos aprendido que crecer no es solo vender más, sino mejorar cada proceso para ofrecer un producto seguro, auténtico y de excelente calidad.

Hemos tenido retos importantes. En nuestros inicios muchos procesos eran empíricos y no contábamos con la documentación ni los estándares que hoy tenemos. Gracias al acompañamiento de entidades como el INVIMA, entendimos la importancia de implementar buenas prácticas, fortalecer nuestros procesos y trabajar con una visión de mejora continua.

Hoy nos sentimos orgullosos de lo que hemos logrado: hemos fortalecido nuestra empresa, ganado la confianza de nuestros clientes y mantenido el compromiso de preservar la tradición de las auténticas achiras huilenses, sin perder nuestra esencia artesanal.

Sabemos que aún hay mucho por recorrer, pero cada desafío nos ha dejado una enseñanza y cada logro nos motiva a seguir creciendo, innovando y llevando productos de calidad a más hogares colombianos.',
  story_future = 'Nuestro sueño es consolidar a Bambuqueras como un referente nacional de las auténticas achiras huilenses, llevando un producto que represente la tradición, la calidad y el orgullo de nuestra región.

En el corto plazo queremos seguir fortaleciendo nuestros procesos, ampliar nuestra presencia en nuevos mercados y puntos de venta, y continuar innovando sin perder la esencia artesanal que nos caracteriza. También queremos generar más oportunidades de empleo y seguir creciendo de manera responsable, siempre de la mano de las buenas prácticas y el mejoramiento continuo.

Más que crecer en tamaño, queremos crecer en confianza, para que cada cliente que pruebe nuestros productos reconozca en Bambuqueras una empresa comprometida con la calidad, la tradición y el desarrollo de Colombia.'
where code = 'EM0007'
  and story_origin is not distinct from 'La empresa Bambuqueras inició en el año 1988 bajo el nombre Bizcochería la Especial, con 2 personas al frente del negocio. Con el pasar de los años y el aumento de las ventas y el éxito de la empresa, nos vimos en la obligación de registrar nuestra marca. Al estar ya ocupado ese nombre con otra empresa, tuvimos que cambiar y renovar nuestro nombre. Actualmente somos Bambuqueras, Un legado muy Especial, somos los mismo de hace 38 años, con la misma receta y misma tradición.'
  and story_present is not distinct from 'Hoy Bambuqueras, antes conocida como Bizcochería La Especial, es una empresa más organizada, comprometida y enfocada en la calidad. A lo largo de este camino hemos aprendido que crecer no es solo vender más, sino mejorar cada proceso para ofrecer un producto seguro, auténtico y de excelente calidad.

Hemos tenido retos importantes. En nuestros inicios muchos procesos eran empíricos y no contábamos con la documentación ni los estándares que hoy tenemos. Gracias al acompañamiento de entidades como el INVIMA, entendimos la importancia de implementar buenas prácticas, fortalecer nuestros procesos y trabajar con una visión de mejora continua.

Hoy nos sentimos orgullosos de lo que hemos logrado: hemos fortalecido nuestra empresa, ganado la confianza de nuestros clientes y mantenido el compromiso de preservar la tradición de las auténticas achiras huilenses, sin perder nuestra esencia artesanal.

Sabemos que aún hay mucho por recorrer, pero cada desafío nos ha dejado una enseñanza y cada logro nos motiva a seguir creciendo, innovando y llevando productos de calidad a más hogares colombianos.'
  and story_future is not distinct from 'Nuestro sueño es consolidar a Bambuqueras como un referente nacional de las auténticas achiras huilenses, llevando un producto que represente la tradición, la calidad y el orgullo de nuestra región.

En el corto plazo queremos seguir fortaleciendo nuestros procesos, ampliar nuestra presencia en nuevos mercados y puntos de venta, y continuar innovando sin perder la esencia artesanal que nos caracteriza. También queremos generar más oportunidades de empleo y seguir creciendo de manera responsable, siempre de la mano de las buenas prácticas y el mejoramiento continuo.

Más que crecer en tamaño, queremos crecer en confianza, para que cada cliente que pruebe nuestros productos reconozca en Bambuqueras una empresa comprometida con la calidad, la tradición y el desarrollo de Colombia.';

-- EM0008 · Macchi Infinite
update public.ambassadors set
  story_origin = 'Macchi Infinite nace en Neiva como respuesta al clima, reinterpretando el abanico desde una mirada contemporánea que dialoga con la identidad del territorio huilense, donde el calor, la elegancia y las dinámicas sociales han hecho del abanico un objeto cotidiano que hoy se transforma en símbolo de estilo y expresión.

El ensamblaje y los acabados se realizan manualmente, garantizando precisión, detalle y carácter artesanal en cada pieza.

Macchi Infinite introduce un sistema de abanico transformable mediante forros intercambiables y uso manos libres, proponiendo una evolución del objeto tradicional hacia un accesorio adaptable, funcional y contemporáneo.',
  story_present = 'Hoy Macchi Infinite es una marca más sólida, con una identidad clara y una propuesta diferenciadora. En el camino seguimos aprendiendo que emprender implica adaptarse, escuchar, mejorar continuamente y ser resilientes. Hemos enfrentado retos propios del crecimiento, pero cada uno nos ha dejado aprendizajes valiosos. Nos llena de orgullo haber llegado a nuevos espacios comerciales, participar en importantes vitrinas y, sobre todo, construir una comunidad de clientes que valora nuestro trabajo. Seguimos creciendo con la misma pasión con la que empezamos y con la convicción de que aún queda mucho camino por recorrer.',
  story_future = 'Nuestro sueño es consolidar a Macchi Infinite como una marca colombiana de referencia en accesorios artesanales de diseño, llevando nuestras creaciones a más ciudades, fortaleciendo nuestra presencia en marketplaces y canales digitales, y abriendo oportunidades en mercados internacionales. Queremos seguir innovando, generar empleo, trabajar de la mano con más artesanos y demostrar que desde el Huila es posible crear productos con identidad, calidad y proyección global.'
where code = 'EM0008'
  and story_origin is not distinct from 'Macchi Infinite nace en Neiva como respuesta al clima, reinterpretando el abanico desde una mirada contemporánea que dialoga con la identidad del territorio huilense, donde el calor, la elegancia y las dinámicas sociales han hecho del abanico un objeto cotidiano que hoy se transforma en símbolo de estilo y expresión.

