-- EM0017 · Herencia Obsequios Huilenses
update public.ambassadors set
  story_origin = 'Nació como una forma de ofrecer a los turistas que visitaban San Agustín souvenirs livianos, resistentes, coloridos y útiles que pudieran llevar como recuerdo de su viaje. Luego se convirtió en la marca de los huilenses y pasamos a atender a turistas de todo el departamento.',
  story_present = 'Hoy en día, la empresa está un poco quieta debido a mis ocupaciones laborales, pero mi deseo es continuar con el trabajo que traía, ya que somos una marca reconocida en el departamento, con una comunidad fuerte. Hacemos presencia con puntos aliados en Tiendas de Promisión, el aeropuerto de Neiva, el aeropuerto de Pitalito y el café La Meca, en Pitalito.',
  story_future = 'Volver a tener nuestro punto de venta propio.'
where code = 'EM0017'
  and story_origin is not distinct from 'Como una forma de ofrecer a turistas que visitaban San Agustín, souvenirs, livianos, resistentes, coloridos, y útiles que pudieran llevar como recuerdo de su viaje, luego se convirtió en la marca de los Huilenses y pasamos a atender a turistas de todo el departamento.'
  and story_present is not distinct from 'Hoy en día, la empresa esta un poco quieta, debido a mis ocupaciones laborales, pero mi deseo de continuar con el trabajo que traía, lo anterior ya que somos una marca reconocida en el departamento, con una comunidad fuerte, hacemos presencia con puntos aliados en Tiendas de promisión, aeropuerto de Neiva, aeropuerto de Pitalito y en el café la Meca en Pitalito.'
  and story_future is not distinct from 'Volver a tener nuestro punto de venta propio.';

